from pathlib import Path
import zipfile as zp
import tempfile
import shutil
import lzma
import re

from taf.rfrl.procedures.resources.python.logger import log_input_and_output

OUTPUT_BLACKBOX_TXT_FILE_NAME = "blackbox.txt"


class SnapshotExtractor:

    def __init__(self):
        """
        Initializes the SnapshotExtractor object with the root and extract directories set to None.
        If the root directory will not be set in the future, it will be created as a temporary directory.
        """
        self._root_extract_dir = None
        self._extract_dir = None

    @log_input_and_output
    def copy_blackbox_files_content_to_blackbox_txt(self, snapshot_zip_path, output_dir):
        """
        Copies the content of blackbox files into a single text file.
        This function searches for blackbox files in the given snapshot zip file, reads their content,
        and writes it into a single text file named 'blackbox.txt' in the specified output directory.
        Each blackbox file's content is written into the text file with a header containing the snapshot path
        of the blackbox file.
        Args:
          :param snapshot_zip_path: (str) The path to the snapshot zip file to search for blackbox files.
          :param output_dir: (str) The directory where the 'blackbox.txt' file will be created.
        Returns:
            None
        """
        self.root_extract_dir = Path(output_dir, "extracted_snapshot")
        xz_name_pattern = re.compile(".*blackbox\\.xz$")
        try:
            blackbox_files = self._get_paths_of_files_extracted_from_xz_zip_nested_in_snapshot_zip(
                snapshot_zip_path=snapshot_zip_path, xz_name_pattern=xz_name_pattern)
            with (open(Path(output_dir, OUTPUT_BLACKBOX_TXT_FILE_NAME), "w") as blackbox_txt):
                for unpacked_blackbox, bbox_path in blackbox_files:
                    emphase_len = len(bbox_path)
                    bbox_zip_path_emphasised = "_" * emphase_len + "\n" + bbox_path + "\n" + "-" * emphase_len + "\n"
                    blackbox_txt.write(bbox_zip_path_emphasised)
                    with open(unpacked_blackbox, "r") as source_file:
                        blackbox_txt.write(source_file.read())
                    blackbox_txt.write("\n")
        finally:
            shutil.rmtree(self.root_extract_dir, ignore_errors=True)
            self._extract_dir = None

    @property
    def root_extract_dir(self):
        """ Returns the root directory where the extracted files are stored. """
        if self._root_extract_dir is None:
            self._root_extract_dir = tempfile.mkdtemp()
        return self._root_extract_dir

    @root_extract_dir.setter
    def root_extract_dir(self, value):
        """ Sets the root directory where the extracted files are stored. """
        self._root_extract_dir = Path(value)
        Path.mkdir(Path(self._root_extract_dir), exist_ok=True)

    @property
    def extract_dir(self):
        """ Returns the directory where the extracted files are stored. """
        if self._extract_dir is None:
            self._extract_dir = Path(self.root_extract_dir)
        return self._extract_dir

    @extract_dir.setter
    def extract_dir(self, value):
        """ Sets the directory where the extracted files are stored. """
        self._extract_dir = Path(self.root_extract_dir, value)
        Path.mkdir(Path(self._extract_dir), exist_ok=True)

    @log_input_and_output
    def _get_paths_of_files_extracted_from_xz_zip_nested_in_snapshot_zip(self, snapshot_zip_path, xz_name_pattern):
        """
        Extracts and returns the paths of files from a mathing nested .xz archive within a .zip files
        in the snapshot.zip
        This function searches for .xz archives ending with a specified name within the given snapshot zip file.
        It extracts these .xz archives and returns the paths and archive paths of the files within them.
        Args:
          :param snapshot_zip_path: (str) The path to the snapshot zip file to search for .xz archives.
          :param xz_name_pattern: (str): The pattern of the .xz archive names to search for.
        Returns:
           list: A list of tuples, where each tuple contains the path of a file extracted from an .xz archive and
                 the path of archives in the snapshot the .xz archive the file was extracted from.
                 The list is sorted to have the blackbox files in alphabetical order (Smod first and next basebands).
        """
        found_files_paths_and_paths_in_snapshot = []
        for extracted_zip_file in self._extract_zip_file(snapshot_zip_path):
            if zp.is_zipfile(extracted_zip_file):
                self.extract_dir = extracted_zip_file.stem
                for extracted_2nd_lvl_file in self._extract_zip_file(extracted_zip_file):
                    if re.match(xz_name_pattern, extracted_2nd_lvl_file.name):
                        self.extract_dir = f"XZ_{extracted_2nd_lvl_file.stem}"
                        for file_ in self._extract_xz_file(extracted_2nd_lvl_file):
                            snapshot_path = f"{extracted_zip_file.name}/{extracted_2nd_lvl_file.name}/{file_.name}"
                            found_files_paths_and_paths_in_snapshot.append((file_, snapshot_path))
        return sorted(found_files_paths_and_paths_in_snapshot)

    @log_input_and_output
    def _extract_zip_file(self, zipfile):
        """
        Extracts the content of a single level of a zip file.
        This function takes a zip file, extracts its content into a extract directory, and returns
        an iterator over the items in the directory.
        Args:
          :param zipfile: (str or Path) The path to the zip file to extract.
        Returns:
            iterator: An iterator over the items in the  directory where the zip files were extracted.
        """
        with zp.ZipFile(zipfile, 'r') as zip_ref:
            zip_ref.extractall(self.extract_dir)
        return Path(self.extract_dir).iterdir()

    @log_input_and_output
    def _extract_xz_file(self, xzfile):
        """
        Extracts the content of a .xz file.
        This function takes a .xz file, extracts its content into a extract_dir directory, and returns
        an iterator over the items in the directory.
        Args:
          :param xzfile: (str or Path) The path to the .xz file to extract.
        Returns:
          iterator: An iterator over the items in the directory where the .xz files were extracted.
        """
        with lzma.open(xzfile, 'rb') as f:
            with open(Path(self.extract_dir, xzfile.stem), 'wb') as f_out:
                shutil.copyfileobj(f, f_out)
        return Path(self.extract_dir).iterdir()
